def f(inputs: List[str]) -> List[int]:
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    def is_lychrel(x: str) -> bool:
        for _ in range(50):
            x = str(int(x) + int(x[::-1]))
            if is_palindrome(x):
                return False
        return True

    return [is_lychrel(x) for x in inputs]
```

